-- 1. MAXIMUS — SAT_ASSESSMENT_HEADER   [Implemented]
-- Same comparison as DM-A2 (latest satellite row vs the latest RAW record, model logic
-- recomputed from RAW) but the sample is the most recently loaded keys, i.e. the keys
-- that just changed -- where a stale current row would show. standard satellite,
-- automate_dv.sat; PK ASSESSMENT_HKEY; 1 RECORD_SOURCE group(s):
-- MAXIMUS_NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_TELE_VERIFICATION_DETAILS [4 col(s)].
----------------------------------------------------------------------------------------
with s1 as (  -- the 100 most recently loaded keys of this RECORD_SOURCE (latest changes)
    select ASSESSMENT_HKEY as hkey from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_ASSESSMENT_HEADER
     where RECORD_SOURCE = 'MAXIMUS_NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_TELE_VERIFICATION_DETAILS'
     group by ASSESSMENT_HKEY
     order by max(LOAD_DATETIME) desc, hkey
     limit 100
),
c1 as (  -- latest satellite row per sampled key
    select ASSESSMENT_HKEY as hkey,
           to_varchar(ASSESSMENT_END_TIME) as ASSESSMENT_END_TIME,
           to_varchar(ASSESSMENT_START_TIME) as ASSESSMENT_START_TIME,
           to_varchar(ASSESSMENT_STATUS) as ASSESSMENT_STATUS,
           to_varchar(REQUESTED_DATE) as REQUESTED_DATE
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_ASSESSMENT_HEADER
     where RECORD_SOURCE = 'MAXIMUS_NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_TELE_VERIFICATION_DETAILS'
       and ASSESSMENT_HKEY in (select hkey from s1)
    qualify rank() over (partition by ASSESSMENT_HKEY order by LOAD_DATETIME desc) = 1
),
e1 as (  -- expected value(s) at the latest RAW load timestamp per key
    select *
      from (
        -- via stg_mt__uwr_pol_tele
        select MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_ASSESSMENT|' || (nullif(trim(case when nullif(trim((nullif(trim(to_varchar("TRANSACTION_ID")), ''))),'') is not null then 'TELEVERIF:' || nullif(trim((nullif(trim(to_varchar("TRANSACTION_ID")), ''))), '') end),'')) AS VARCHAR))), '')) as hkey,
               (nullif(trim(to_varchar("REC_REFRESH_AT")), '')) as ldts,
               to_varchar((nullif(trim(to_varchar("END_TIME")), ''))) as ASSESSMENT_END_TIME,
               to_varchar((nullif(trim(to_varchar("START_TIME")), ''))) as ASSESSMENT_START_TIME,
               to_varchar((nullif(trim(to_varchar("TELE_VARIFICATION_STATUS")), ''))) as ASSESSMENT_STATUS,
               to_varchar((nullif(trim(to_varchar("TELE_VARIFICATION_INITIATED_DATE")), ''))) as REQUESTED_DATE
          from RAW.MAXIMUS_TRAVEL.NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_TELE_VERIFICATION_DETAILS
      )
     where hkey in (select hkey from s1) and ldts is not null
    qualify rank() over (partition by hkey order by ldts desc) = 1
),
r1 as (
    select 'ASSESSMENT_END_TIME' as column_name, c.hkey, c.ASSESSMENT_END_TIME as sat_value,
           max(iff(equal_null(c.ASSESSMENT_END_TIME, e.ASSESSMENT_END_TIME), 1, 0)) as matched, count(e.hkey) as src_rows, min(e.ASSESSMENT_END_TIME) as src_value
      from c1 c left join e1 e on e.hkey = c.hkey
     group by c.hkey, c.ASSESSMENT_END_TIME
    union all
    select 'ASSESSMENT_START_TIME' as column_name, c.hkey, c.ASSESSMENT_START_TIME as sat_value,
           max(iff(equal_null(c.ASSESSMENT_START_TIME, e.ASSESSMENT_START_TIME), 1, 0)) as matched, count(e.hkey) as src_rows, min(e.ASSESSMENT_START_TIME) as src_value
      from c1 c left join e1 e on e.hkey = c.hkey
     group by c.hkey, c.ASSESSMENT_START_TIME
    union all
    select 'ASSESSMENT_STATUS' as column_name, c.hkey, c.ASSESSMENT_STATUS as sat_value,
           max(iff(equal_null(c.ASSESSMENT_STATUS, e.ASSESSMENT_STATUS), 1, 0)) as matched, count(e.hkey) as src_rows, min(e.ASSESSMENT_STATUS) as src_value
      from c1 c left join e1 e on e.hkey = c.hkey
     group by c.hkey, c.ASSESSMENT_STATUS
    union all
    select 'REQUESTED_DATE' as column_name, c.hkey, c.REQUESTED_DATE as sat_value,
           max(iff(equal_null(c.REQUESTED_DATE, e.REQUESTED_DATE), 1, 0)) as matched, count(e.hkey) as src_rows, min(e.REQUESTED_DATE) as src_value
      from c1 c left join e1 e on e.hkey = c.hkey
     group by c.hkey, c.REQUESTED_DATE
)
select 'MAXIMUS' as project, 'SAT_ASSESSMENT_HEADER' as satellite, 'MAXIMUS_NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_TELE_VERIFICATION_DETAILS' as record_source, column_name,
       count(*) as keys_compared,
       count_if(src_rows > 0 and matched = 1) as matched,
       count_if(src_rows > 0 and matched = 0) as mismatched,
       count_if(src_rows = 0) as no_source_row,
       array_slice(array_agg(iff(src_rows > 0 and matched = 0, object_construct('hkey', to_varchar(hkey, 'HEX'), 'sat', sat_value, 'src', src_value), null))
                   within group (order by hkey), 0, 3) as mismatch_examples,
       iff(mismatched = 0 and no_source_row = 0, 'PASS', 'FAIL') as status
  from r1
 group by column_name
order by record_source, column_name;



