-- 25. MAXIMUS — SAT_COMMON_ADMIN_GEOGRAPHY   [Implemented]
-- Same comparison as DM-A2 (latest satellite row vs the latest RAW record, model logic
-- recomputed from RAW) but the sample is the most recently loaded keys, i.e. the keys
-- that just changed -- where a stale current row would show. standard satellite,
-- automate_dv.sat; PK LOCATION_HKEY; 1 RECORD_SOURCE group(s):
-- MAXIMUS_NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS_CLAIM_ATTRIBUTE_PROPERTIES_PIVOT_VW [5
-- col(s)].
----------------------------------------------------------------------------------------
with s1 as (  -- the 100 most recently loaded keys of this RECORD_SOURCE (latest changes)
    select LOCATION_HKEY as hkey from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_COMMON_ADMIN_GEOGRAPHY
     where RECORD_SOURCE = 'MAXIMUS_NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS_CLAIM_ATTRIBUTE_PROPERTIES_PIVOT_VW'
     group by LOCATION_HKEY
     order by max(LOAD_DATETIME) desc, hkey
     limit 100
),
c1 as (  -- latest satellite row per sampled key
    select LOCATION_HKEY as hkey,
           to_varchar(COUNTRY_CODE) as COUNTRY_CODE,
           to_varchar(DISTRICT_NAME) as DISTRICT_NAME,
           to_varchar(STATE_CODE) as STATE_CODE,
           to_varchar(STATE_NAME) as STATE_NAME,
           to_varchar(TALUKA_NAME) as TALUKA_NAME
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_COMMON_ADMIN_GEOGRAPHY
     where RECORD_SOURCE = 'MAXIMUS_NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS_CLAIM_ATTRIBUTE_PROPERTIES_PIVOT_VW'
       and LOCATION_HKEY in (select hkey from s1)
    qualify rank() over (partition by LOCATION_HKEY order by LOAD_DATETIME desc) = 1
),
e1 as (  -- expected value(s) at the latest RAW load timestamp per key
    select *
      from (
        -- via resolved_mt__clm_clmd_clmap_pv
        select MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_LOCATION|' || (nullif(trim(case when coalesce(nullif(trim((nullif(trim(to_varchar("CUSTOMER_LOCATION_BY_STATE")), ''))),''), nullif(trim((nullif(trim(to_varchar("CUSTOMER_LOCATION_BY_DISTRICT")), ''))),''), nullif(trim((nullif(trim(to_varchar("CUSTOMER_LOCATION_BY_TEHSIL")), ''))),'')) is not null then md5(upper(regexp_replace(trim(nullif(trim(coalesce(nullif(trim((nullif(trim(to_varchar("CUSTOMER_LOCATION_BY_STATE")), ''))), ''), '') || '|' || coalesce(nullif(trim((nullif(trim(to_varchar("CUSTOMER_LOCATION_BY_DISTRICT")), ''))), ''), '') || '|' || coalesce(nullif(trim((nullif(trim(to_varchar("CUSTOMER_LOCATION_BY_TEHSIL")), ''))), ''), '')), '||')), '[[:space:]]+', ' '))) end),'')) AS VARCHAR))), '')) as hkey,
               (nullif(trim(to_varchar("REC_REFRESH_AT")), '')) as ldts,
               to_varchar((nullif(trim(to_varchar("STORED_COUNTRY_CODE")), ''))) as COUNTRY_CODE,
               to_varchar((nullif(trim(to_varchar("CUSTOMER_LOCATION_BY_DISTRICT")), ''))) as DISTRICT_NAME,
               to_varchar((nullif(trim(to_varchar("STORED_STATE_CODE")), ''))) as STATE_CODE,
               to_varchar((nullif(trim(to_varchar("CUSTOMER_LOCATION_BY_STATE")), ''))) as STATE_NAME,
               to_varchar((nullif(trim(to_varchar("CUSTOMER_LOCATION_BY_TEHSIL")), ''))) as TALUKA_NAME
          from RAW.MAXIMUS_TRAVEL.NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS_CLAIM_ATTRIBUTE_PROPERTIES_PIVOT_VW
      )
     where hkey in (select hkey from s1) and ldts is not null
    qualify rank() over (partition by hkey order by ldts desc) = 1
),
r1 as (
    select 'COUNTRY_CODE' as column_name, c.hkey, c.COUNTRY_CODE as sat_value,
           max(iff(equal_null(c.COUNTRY_CODE, e.COUNTRY_CODE), 1, 0)) as matched, count(e.hkey) as src_rows, min(e.COUNTRY_CODE) as src_value
      from c1 c left join e1 e on e.hkey = c.hkey
     group by c.hkey, c.COUNTRY_CODE
    union all
    select 'DISTRICT_NAME' as column_name, c.hkey, c.DISTRICT_NAME as sat_value,
           max(iff(equal_null(c.DISTRICT_NAME, e.DISTRICT_NAME), 1, 0)) as matched, count(e.hkey) as src_rows, min(e.DISTRICT_NAME) as src_value
      from c1 c left join e1 e on e.hkey = c.hkey
     group by c.hkey, c.DISTRICT_NAME
    union all
    select 'STATE_CODE' as column_name, c.hkey, c.STATE_CODE as sat_value,
           max(iff(equal_null(c.STATE_CODE, e.STATE_CODE), 1, 0)) as matched, count(e.hkey) as src_rows, min(e.STATE_CODE) as src_value
      from c1 c left join e1 e on e.hkey = c.hkey
     group by c.hkey, c.STATE_CODE
    union all
    select 'STATE_NAME' as column_name, c.hkey, c.STATE_NAME as sat_value,
           max(iff(equal_null(c.STATE_NAME, e.STATE_NAME), 1, 0)) as matched, count(e.hkey) as src_rows, min(e.STATE_NAME) as src_value
      from c1 c left join e1 e on e.hkey = c.hkey
     group by c.hkey, c.STATE_NAME
    union all
    select 'TALUKA_NAME' as column_name, c.hkey, c.TALUKA_NAME as sat_value,
           max(iff(equal_null(c.TALUKA_NAME, e.TALUKA_NAME), 1, 0)) as matched, count(e.hkey) as src_rows, min(e.TALUKA_NAME) as src_value
      from c1 c left join e1 e on e.hkey = c.hkey
     group by c.hkey, c.TALUKA_NAME
)
select 'MAXIMUS' as project, 'SAT_COMMON_ADMIN_GEOGRAPHY' as satellite, 'MAXIMUS_NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS_CLAIM_ATTRIBUTE_PROPERTIES_PIVOT_VW' as record_source, column_name,
       count(*) as keys_compared,
       count_if(src_rows > 0 and matched = 1) as matched,
       count_if(src_rows > 0 and matched = 0) as mismatched,
       count_if(src_rows = 0) as no_source_row,
       array_slice(array_agg(iff(src_rows > 0 and matched = 0, object_construct('hkey', to_varchar(hkey, 'HEX'), 'sat', sat_value, 'src', src_value), null))
                   within group (order by hkey), 0, 3) as mismatch_examples,
       iff(mismatched = 0 and no_source_row = 0, 'PASS', 'FAIL') as status
  from r1
 group by column_name
order by record_source, column_name;



