-- 31. MAXIMUS — SAT_COMMON_GEO   [Implemented]
-- Same comparison as DM-A2 (latest satellite row vs the latest RAW record, model logic
-- recomputed from RAW) but the sample is the most recently loaded keys, i.e. the keys
-- that just changed -- where a stale current row would show. standard satellite,
-- automate_dv.sat; PK LOCATION_HKEY; 3 RECORD_SOURCE group(s):
-- MAXIMUS_NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_INSURED_DETAILS_MEMBER_DETAILS_PARTY_ADDRESS_ADDRESS_PROPERTY_PIVOT_VW
-- [3 col(s)],
-- MAXIMUS_NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_OFFICE_DETAILS_OFFICE_ADDRESS_ADDRESS_PROPERTY_PIVOT_VW
-- [3 col(s)],
-- MAXIMUS_NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_PROPOSER_DETAILS_PARTY_ADDRESS_ADDRESS_PROPERTY_PIVOT_VW
-- [3 col(s)].
----------------------------------------------------------------------------------------
with s1 as (  -- the 100 most recently loaded keys of this RECORD_SOURCE (latest changes)
    select LOCATION_HKEY as hkey from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_COMMON_GEO
     where RECORD_SOURCE = 'MAXIMUS_NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_INSURED_DETAILS_MEMBER_DETAILS_PARTY_ADDRESS_ADDRESS_PROPERTY_PIVOT_VW'
     group by LOCATION_HKEY
     order by max(LOAD_DATETIME) desc, hkey
     limit 100
),
c1 as (  -- latest satellite row per sampled key
    select LOCATION_HKEY as hkey,
           to_varchar(ALTITUDE) as ALTITUDE,
           to_varchar(LATITUDE) as LATITUDE,
           to_varchar(LONGITUDE) as LONGITUDE
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_COMMON_GEO
     where RECORD_SOURCE = 'MAXIMUS_NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_INSURED_DETAILS_MEMBER_DETAILS_PARTY_ADDRESS_ADDRESS_PROPERTY_PIVOT_VW'
       and LOCATION_HKEY in (select hkey from s1)
    qualify rank() over (partition by LOCATION_HKEY order by LOAD_DATETIME desc) = 1
),
e1 as (  -- expected value(s) at the latest RAW load timestamp per key
    select *
      from (
        -- via resolved_mt__uwr_pol_ins_mbr_pa_address_prop_pv
        select MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_LOCATION|' || (nullif(trim(case when coalesce(nullif(trim((nullif(trim(to_varchar("AREA")), ''))),''), nullif(trim((nullif(trim(to_varchar("LAND_MARK")), ''))),''), nullif(trim(((nullif(trim(to_varchar("CITY")), '')))),''), nullif(trim((nullif(trim(to_varchar("STATE")), ''))),''), nullif(trim((nullif(trim(to_varchar("PINCODE")), ''))),'')) is not null then md5(upper(regexp_replace(trim(nullif(trim(coalesce(nullif(trim((nullif(trim(to_varchar("AREA")), ''))), ''), '') || '#' || coalesce(nullif(trim((nullif(trim(to_varchar("LAND_MARK")), ''))), ''), '') || '#' || coalesce(nullif(trim(((nullif(trim(to_varchar("CITY")), '')))), ''), '') || '#' || coalesce(nullif(trim((nullif(trim(to_varchar("STATE")), ''))), ''), '') || '#' || coalesce(nullif(trim((nullif(trim(to_varchar("PINCODE")), ''))), ''), '')), '####')), '[[:space:]]+', ' '))) end),'')) AS VARCHAR))), '')) as hkey,
               (nullif(trim(to_varchar("REC_REFRESH_AT")), '')) as ldts,
               to_varchar((nullif(trim(to_varchar("GEO_COORDINATE_ALTITUDE")), ''))) as ALTITUDE,
               to_varchar((nullif(trim(to_varchar("GEO_COORDINATE_LATITUDE")), ''))) as LATITUDE,
               to_varchar((nullif(trim(to_varchar("GEO_COORDINATE_LONGITUDE")), ''))) as LONGITUDE
          from RAW.MAXIMUS_TRAVEL.NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_INSURED_DETAILS_MEMBER_DETAILS_PARTY_ADDRESS_ADDRESS_PROPERTY_PIVOT_VW
      )
     where hkey in (select hkey from s1) and ldts is not null
    qualify rank() over (partition by hkey order by ldts desc) = 1
),
r1 as (
    select 'ALTITUDE' as column_name, c.hkey, c.ALTITUDE as sat_value,
           max(iff(equal_null(c.ALTITUDE, e.ALTITUDE), 1, 0)) as matched, count(e.hkey) as src_rows, min(e.ALTITUDE) as src_value
      from c1 c left join e1 e on e.hkey = c.hkey
     group by c.hkey, c.ALTITUDE
    union all
    select 'LATITUDE' as column_name, c.hkey, c.LATITUDE as sat_value,
           max(iff(equal_null(c.LATITUDE, e.LATITUDE), 1, 0)) as matched, count(e.hkey) as src_rows, min(e.LATITUDE) as src_value
      from c1 c left join e1 e on e.hkey = c.hkey
