with s1 as (  -- the 100 most recently loaded keys of this RECORD_SOURCE (latest changes)
    select PARTY_HKEY as hkey from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_PARTY_IDENTITY
     where RECORD_SOURCE = 'MAXIMUS_NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS_CLAIM_ATTRIBUTE_PROPERTIES_PIVOT_VW'
     group by PARTY_HKEY
     order by max(LOAD_DATETIME) desc, hkey
     limit 100
),
c1 as (  -- latest satellite row per sampled key
    select PARTY_HKEY as hkey,
           to_varchar(DATE_OF_BIRTH) as DATE_OF_BIRTH,
           to_varchar(PARTY_FULL_NAME) as PARTY_FULL_NAME
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_PARTY_IDENTITY
     where RECORD_SOURCE = 'MAXIMUS_NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS_CLAIM_ATTRIBUTE_PROPERTIES_PIVOT_VW'
       and PARTY_HKEY in (select hkey from s1)
    qualify rank() over (partition by PARTY_HKEY order by LOAD_DATETIME desc) = 1
),
e1 as (  -- expected value(s) at the latest RAW load timestamp per key
    select *
      from (
        -- via resolved_mt__clm_clmd_clmap_pv
        select MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || (nullif(trim(case when nullif(trim((nullif(trim(to_varchar("CUSTOMERID")), ''))),'') is not null then nullif(trim((nullif(trim(to_varchar("CUSTOMERID")), ''))), '') end),'')) AS VARCHAR))), '')) as hkey,
               (nullif(trim(to_varchar("REC_REFRESH_AT")), '')) as ldts,
               to_varchar((nullif(trim(to_varchar("ENTER_DOB")), ''))) as DATE_OF_BIRTH,
               to_varchar(coalesce((nullif(trim(to_varchar("INSURED_NAME")), '')), (nullif(trim(to_varchar("MEMBER_NAME")), '')), (nullif(trim(to_varchar("SUB_IMD_NAME")), '')))) as PARTY_FULL_NAME
          from RAW.MAXIMUS_TRAVEL.NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS_CLAIM_ATTRIBUTE_PROPERTIES_PIVOT_VW
      )
     where hkey in (select hkey from s1) and ldts is not null
    qualify rank() over (partition by hkey order by ldts desc) = 1
),
r1 as (
    select 'DATE_OF_BIRTH' as column_name, c.hkey, c.DATE_OF_BIRTH as sat_value,
           max(iff(equal_null(c.DATE_OF_BIRTH, e.DATE_OF_BIRTH), 1, 0)) as matched, count(e.hkey) as src_rows, min(e.DATE_OF_BIRTH) as src_value
      from c1 c left join e1 e on e.hkey = c.hkey
     group by c.hkey, c.DATE_OF_BIRTH
    union all
    select 'PARTY_FULL_NAME' as column_name, c.hkey, c.PARTY_FULL_NAME as sat_value,
           max(iff(equal_null(c.PARTY_FULL_NAME, e.PARTY_FULL_NAME), 1, 0)) as matched, count(e.hkey) as src_rows, min(e.PARTY_FULL_NAME) as src_value
      from c1 c left join e1 e on e.hkey = c.hkey
     group by c.hkey, c.PARTY_FULL_NAME
),
