----------------------------------------------------------------------------------------
-- 66. MAXIMUS — SAT_PARTY_INDIVIDUAL_DEMOGRAPHICS   [Implemented]
-- Same comparison as DM-A2 (latest satellite row vs the latest RAW record, model logic
-- recomputed from RAW) but the sample is the most recently loaded keys, i.e. the keys
-- that just changed -- where a stale current row would show. standard satellite,
-- automate_dv.sat; PK PARTY_HKEY; 2 RECORD_SOURCE group(s):
-- MAXIMUS_NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_INSURED_DETAILS_MEMBER_DETAILS_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW
-- [4 col(s)],
-- MAXIMUS_NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_PROPOSER_DETAILS_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW
-- [6 col(s)].
----------------------------------------------------------------------------------------
with s1 as (  -- the 100 most recently loaded keys of this RECORD_SOURCE (latest changes)
    select PARTY_HKEY as hkey from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_PARTY_INDIVIDUAL_DEMOGRAPHICS
     where RECORD_SOURCE = 'MAXIMUS_NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_INSURED_DETAILS_MEMBER_DETAILS_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW'
     group by PARTY_HKEY
     order by max(LOAD_DATETIME) desc, hkey
     limit 100
),
c1 as (  -- latest satellite row per sampled key
    select PARTY_HKEY as hkey,
           to_varchar(EDUCATIONAL_QUALIFICATION) as EDUCATIONAL_QUALIFICATION,
           to_varchar(FATHER_NAME) as FATHER_NAME,
           to_varchar(MARITAL_STATUS) as MARITAL_STATUS,
           to_varchar(SPOUSE_NAME) as SPOUSE_NAME
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_PARTY_INDIVIDUAL_DEMOGRAPHICS
     where RECORD_SOURCE = 'MAXIMUS_NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_INSURED_DETAILS_MEMBER_DETAILS_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW'
       and PARTY_HKEY in (select hkey from s1)
    qualify rank() over (partition by PARTY_HKEY order by LOAD_DATETIME desc) = 1
),
e1 as (  -- expected value(s) at the latest RAW load timestamp per key
    select *
      from (
        -- via resolved_mt__uwr_pol_ins_mbr_pp_sp_pv
        select MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || (nullif(trim(case when nullif(trim(w0_party_code),'') is not null then nullif(trim(w0_party_code), '') end),'')) AS VARCHAR))), '')) as hkey,
               (nullif(trim(to_varchar("REC_REFRESH_AT")), '')) as ldts,
               to_varchar((nullif(trim(to_varchar("EDUCATION")), ''))) as EDUCATIONAL_QUALIFICATION,
               to_varchar((nullif(trim(to_varchar("FATHER_NAME")), ''))) as FATHER_NAME,
               to_varchar((nullif(trim(to_varchar("MARITAL_STATUS")), ''))) as MARITAL_STATUS,
               to_varchar((nullif(trim(to_varchar("SPOUSE_NAME")), ''))) as SPOUSE_NAME
          from RAW.MAXIMUS_TRAVEL.NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_INSURED_DETAILS_MEMBER_DETAILS_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW
      )
     where hkey in (select hkey from s1) and ldts is not null
    qualify rank() over (partition by hkey order by ldts desc) = 1
),
r1 as (
    select 'EDUCATIONAL_QUALIFICATION' as column_name, c.hkey, c.EDUCATIONAL_QUALIFICATION as sat_value,
           max(iff(equal_null(c.EDUCATIONAL_QUALIFICATION, e.EDUCATIONAL_QUALIFICATION), 1, 0)) as matched, count(e.hkey) as src_rows, min(e.EDUCATIONAL_QUALIFICATION) as src_value
      from c1 c left join e1 e on e.hkey = c.hkey
     group by c.hkey, c.EDUCATIONAL_QUALIFICATION
    union all
    select 'FATHER_NAME' as column_name, c.hkey, c.FATHER_NAME as sat_value,
           max(iff(equal_null(c.FATHER_NAME, e.FATHER_NAME), 1, 0)) as matched, count(e.hkey) as src_rows, min(e.FATHER_NAME) as src_value
      from c1 c left join e1 e on e.hkey = c.hkey
     group by c.hkey, c.FATHER_NAME
    union all
    select 'MARITAL_STATUS' as column_name, c.hkey, c.MARITAL_STATUS as sat_value,
           max(iff(equal_null(c.MARITAL_STATUS, e.MARITAL_STATUS), 1, 0)) as matched, count(e.hkey) as src_rows, min(e.MARITAL_STATUS) as src_value
      from c1 c left join e1 e on e.hkey = c.hkey
     group by c.hkey, c.MARITAL_STATUS
    union all
    select 'SPOUSE_NAME' as column_name, c.hkey, c.SPOUSE_NAME as sat_value,
           max(iff(equal_null(c.SPOUSE_NAME, e.SPOUSE_NAME), 1, 0)) as matched, count(e.hkey) as src_rows, min(e.SPOUSE_NAME) as src_value
      from c1 c left join e1 e on e.hkey = c.hkey
     group by c.hkey, c.SPOUSE_NAME
),
s2 as (  -- the 100 most recently loaded keys of this RECORD_SOURCE (latest changes)
    select PARTY_HKEY as hkey from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_PARTY_INDIVIDUAL_DEMOGRAPHICS
     where RECORD_SOURCE = 'MAXIMUS_NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_PROPOSER_DETAILS_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW'
     group by PARTY_HKEY
     order by max(LOAD_DATETIME) desc, hkey
     limit 100
),
c2 as (  -- latest satellite row per sampled key
    select PARTY_HKEY as hkey,
           to_varchar(EDUCATIONAL_QUALIFICATION) as EDUCATIONAL_QUALIFICATION,
           to_varchar(FATHER_NAME) as FATHER_NAME,
           to_varchar(HIGHEST_DEGREE) as HIGHEST_DEGREE,
           to_varchar(MARITAL_STATUS) as MARITAL_STATUS,
           to_varchar(SPOUSE_NAME) as SPOUSE_NAME,
           to_varchar(YEARS_IN_CITY) as YEARS_IN_CITY
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_PARTY_INDIVIDUAL_DEMOGRAPHICS
     where RECORD_SOURCE = 'MAXIMUS_NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_PROPOSER_DETAILS_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW'
       and PARTY_HKEY in (select hkey from s2)
    qualify rank() over (partition by PARTY_HKEY order by LOAD_DATETIME desc) = 1
),
e2 as (  -- expected value(s) at the latest RAW load timestamp per key
    select *
      from (
        -- via resolved_mt__uwr_pol_prp_pp_sp_pv
        select MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || (nullif(trim(case when nullif(trim(w0_party_code),'') is not null then nullif(trim(w0_party_code), '') end),'')) AS VARCHAR))), '')) as hkey,
               (nullif(trim(to_varchar("REC_REFRESH_AT")), '')) as ldts,
               to_varchar(coalesce((nullif(trim(to_varchar("EDUCATION")), '')), (nullif(trim(to_varchar("EDUCATIONAL_QUALIFICATION")), '')))) as EDUCATIONAL_QUALIFICATION,
               to_varchar((nullif(trim(to_varchar("FATHER_NAME")), ''))) as FATHER_NAME,
               to_varchar((nullif(trim(to_varchar("HIGHEST_QUALIFICATION_DETAILS")), ''))) as HIGHEST_DEGREE,
               to_varchar((nullif(trim(to_varchar("MARITAL_STATUS")), ''))) as MARITAL_STATUS,
               to_varchar((nullif(trim(to_varchar("SPOUSE_NAME")), ''))) as SPOUSE_NAME,
               to_varchar((nullif(trim(to_varchar("NUMBER_OF_YEARS_RESIDING_IN_THE_CITY_OF_RESIDENCE")), ''))) as YEARS_IN_CITY
          from RAW.MAXIMUS_TRAVEL.NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_PROPOSER_DETAILS_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW
      )
     where hkey in (select hkey from s2) and ldts is not null
    qualify rank() over (partition by hkey order by ldts desc) = 1
),
r2 as (
    select 'EDUCATIONAL_QUALIFICATION' as column_name, c.hkey, c.EDUCATIONAL_QUALIFICATION as sat_value,
           max(iff(equal_null(c.EDUCATIONAL_QUALIFICATION, e.EDUCATIONAL_QUALIFICATION), 1, 0)) as matched, count(e.hkey) as src_rows, min(e.EDUCATIONAL_QUALIFICATION) as src_value
      from c2 c left join e2 e on e.hkey = c.hkey
     group by c.hkey, c.EDUCATIONAL_QUALIFICATION
    union all
    select 'FATHER_NAME' as column_name, c.hkey, c.FATHER_NAME as sat_value,
           max(iff(equal_null(c.FATHER_NAME, e.FATHER_NAME), 1, 0)) as matched, count(e.hkey) as src_rows, min(e.FATHER_NAME) as src_value
      from c2 c left join e2 e on e.hkey = c.hkey
     group by c.hkey, c.FATHER_NAME
    union all
    select 'HIGHEST_DEGREE' as column_name, c.hkey, c.HIGHEST_DEGREE as sat_value,
           max(iff(equal_null(c.HIGHEST_DEGREE, e.HIGHEST_DEGREE), 1, 0)) as matched, count(e.hkey) as src_rows, min(e.HIGHEST_DEGREE) as src_value
      from c2 c left join e2 e on e.hkey = c.hkey
     group by c.hkey, c.HIGHEST_DEGREE
    union all
    select 'MARITAL_STATUS' as column_name, c.hkey, c.MARITAL_STATUS as sat_value,
           max(iff(equal_null(c.MARITAL_STATUS, e.MARITAL_STATUS), 1, 0)) as matched, count(e.hkey) as src_rows, min(e.MARITAL_STATUS) as src_value
      from c2 c left join e2 e on e.hkey = c.hkey
     group by c.hkey, c.MARITAL_STATUS
    union all
    select 'SPOUSE_NAME' as column_name, c.hkey, c.SPOUSE_NAME as sat_value,
           max(iff(equal_null(c.SPOUSE_NAME, e.SPOUSE_NAME), 1, 0)) as matched, count(e.hkey) as src_rows, min(e.SPOUSE_NAME) as src_value
      from c2 c left join e2 e on e.hkey = c.hkey
     group by c.hkey, c.SPOUSE_NAME
    union all
    select 'YEARS_IN_CITY' as column_name, c.hkey, c.YEARS_IN_CITY as sat_value,
           max(iff(equal_null(c.YEARS_IN_CITY, e.YEARS_IN_CITY), 1, 0)) as matched, count(e.hkey) as src_rows, min(e.YEARS_IN_CITY) as src_value
      from c2 c left join e2 e on e.hkey = c.hkey
