               to_varchar(nullif(trim(coalesce(nullif(trim(w1_pol_risk_id), ''), '') || '#' || coalesce(nullif(trim((nullif(trim(to_varchar("PREMIUM_ADJUSTMENT_TYPE")), ''))), ''), '')), '#')) as cdk_1,
