    select POLICY_HKEY as hkey,
           to_varchar(ENDORSEMENT_NUMBER) as cdk_1,
           to_varchar(EFFECTIVE_DATE) as EFFECTIVE_DATE,
           to_varchar(ENDORSEMENT_APPROVAL_DATE) as ENDORSEMENT_APPROVAL_DATE,
