-- 159. MAXIMUS — SAT_AUG_PARTY_LOYALTY_CLASSIFICATION   [Implemented]
-- Same comparison as DM-A2 (latest satellite row vs the latest RAW record, model logic
-- recomputed from RAW) but the sample is the most recently loaded keys, i.e. the keys
-- that just changed -- where a stale current row would show. augmented satellite,
-- automate_dv.ma_sat; PK PARTY_HKEY, child key LOYALTY_CLASSIFICATION_TYPE; 1
-- RECORD_SOURCE group(s):
-- MAXIMUS_NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS_CLAIM_ATTRIBUTE_PROPERTIES_PIVOT_VW [1
-- col(s)]. Multi-active: compared per (key, child key); latest = max LOAD_DATETIME per
-- member.
----------------------------------------------------------------------------------------
with s1 as (  -- the 100 most recently loaded keys of this RECORD_SOURCE (latest changes)
    select PARTY_HKEY as hkey from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_AUG_PARTY_LOYALTY_CLASSIFICATION
     where RECORD_SOURCE = 'MAXIMUS_NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS_CLAIM_ATTRIBUTE_PROPERTIES_PIVOT_VW'
     group by PARTY_HKEY
     order by max(LOAD_DATETIME) desc, hkey
     limit 100
),
c1 as (  -- latest satellite row per sampled key
    select PARTY_HKEY as hkey,
           to_varchar(LOYALTY_CLASSIFICATION_TYPE) as cdk_1,
           to_varchar(LOYALTY_BUCKET) as LOYALTY_BUCKET
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_AUG_PARTY_LOYALTY_CLASSIFICATION
     where RECORD_SOURCE = 'MAXIMUS_NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS_CLAIM_ATTRIBUTE_PROPERTIES_PIVOT_VW'
       and PARTY_HKEY in (select hkey from s1)
    qualify rank() over (partition by PARTY_HKEY, LOYALTY_CLASSIFICATION_TYPE order by LOAD_DATETIME desc) = 1
),
e1 as (  -- expected value(s) at the latest RAW load timestamp per key
    select *
      from (
        -- via up_mt__clm_clmd_clmap_pv__aug_sat_aug_party_loyalty_classification#1
        select MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || (((nullif(trim(case when coalesce(nullif(trim((nullif(trim(to_varchar("UNIQUE_CUSTOMER_ID")), ''))),''), nullif(trim((nullif(trim(to_varchar("CUSTOMERID")), ''))),'')) is not null then coalesce(nullif(trim((nullif(trim(to_varchar("UNIQUE_CUSTOMER_ID")), ''))), ''), nullif(trim((nullif(trim(to_varchar("CUSTOMERID")), ''))), '')) end),'')))) AS VARCHAR))), '')) as hkey,
               to_varchar('NOMENCLATURE') as cdk_1,
               rec_refresh_at as ldts,
               to_varchar(((nullif(trim(to_varchar("LOYALITY_BUCKET_BY_NOMENCLATURE")), '')))) as LOYALTY_BUCKET
          from RAW.MAXIMUS_TRAVEL.NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS_CLAIM_ATTRIBUTE_PROPERTIES_PIVOT_VW
         where (nullif(trim(to_varchar("LOYALITY_BUCKET_BY_NOMENCLATURE")), '')) is not null
        union all
        -- via up_mt__clm_clmd_clmap_pv__aug_sat_aug_party_loyalty_classification#2
        select MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || (((nullif(trim(case when coalesce(nullif(trim((nullif(trim(to_varchar("UNIQUE_CUSTOMER_ID")), ''))),''), nullif(trim((nullif(trim(to_varchar("CUSTOMERID")), ''))),'')) is not null then coalesce(nullif(trim((nullif(trim(to_varchar("UNIQUE_CUSTOMER_ID")), ''))), ''), nullif(trim((nullif(trim(to_varchar("CUSTOMERID")), ''))), '')) end),'')))) AS VARCHAR))), '')) as hkey,
               to_varchar('SEVERITY') as cdk_1,
               rec_refresh_at as ldts,
               to_varchar(((nullif(trim(to_varchar("LOYALITY_BUCKET_BY_SEVERITY")), '')))) as LOYALTY_BUCKET
          from RAW.MAXIMUS_TRAVEL.NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS_CLAIM_ATTRIBUTE_PROPERTIES_PIVOT_VW
