-- [2 col(s)].
----------------------------------------------------------------------------------------
with s1 as (  -- the 100 most recently loaded keys of this RECORD_SOURCE (latest changes)
    select POLICY_HKEY as hkey from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_AUG_POLICY_HEALTH_DECLARATION
     where RECORD_SOURCE = 'MAXIMUS_NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_POLICY_PROPERTY_MULTI_SET_PROPERTY_MULTI_SET_DETAIL_PROPERTY_PIVOT_VW'
     group by POLICY_HKEY
     order by max(LOAD_DATETIME) desc, hkey
     limit 100
),
c1 as (  -- latest satellite row per sampled key
    select POLICY_HKEY as hkey,
           to_varchar(PRE_EXISTING_DISEASE_ONSET_MONTH) as PRE_EXISTING_DISEASE_ONSET_MONTH,
           to_varchar(PRE_EXISTING_DISEASE_ONSET_YEAR) as PRE_EXISTING_DISEASE_ONSET_YEAR
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_AUG_POLICY_HEALTH_DECLARATION
     where RECORD_SOURCE = 'MAXIMUS_NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_POLICY_PROPERTY_MULTI_SET_PROPERTY_MULTI_SET_DETAIL_PROPERTY_PIVOT_VW'
       and POLICY_HKEY in (select hkey from s1)
    qualify rank() over (partition by POLICY_HKEY order by LOAD_DATETIME desc) = 1
),
