-- [15 col(s)]. Multi-active: compared per (key, child key); latest = max LOAD_DATETIME
-- per member.
----------------------------------------------------------------------------------------
with s1 as (  -- the 100 most recently loaded keys of this RECORD_SOURCE (latest changes)
    select QUOTE_HKEY as hkey from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_AUG_QUOTE_COVER_DETAIL
     where RECORD_SOURCE = 'MAXIMUS_NONHLTH_TRV_UWR_VW_DATA_QUOTE_PARAM_DETAILS_RISK_LIST_RISK_COVER_RISK_COVER_PROPERTY_RULE_LIST_PIVOT_VW'
     group by QUOTE_HKEY
     order by max(LOAD_DATETIME) desc, hkey
     limit 100
),
c1 as (  -- latest satellite row per sampled key
    select QUOTE_HKEY as hkey,
           to_varchar(COVERAGE_REFERENCE) as cdk_1,
           to_varchar(COVERAGE_SEQUENCE) as cdk_2,
           to_varchar(BENEFIT_UNIT_IN_HOURS) as BENEFIT_UNIT_IN_HOURS,
           to_varchar(COVER_PERIOD) as COVER_PERIOD,
